import type { AdminLocale } from "./admin-labels";

/**
 * Per-page admin label table. Keys are dot-namespaced by page and the values
 * are full localisations across every supported `AdminLocale`.
 *
 * To add a new translatable string:
 *   1. Pick a page-namespaced key (e.g. `"posts.searchPlaceholder"`).
 *   2. Add an entry below with `en` plus all other locales.
 *   3. Use `getPageT(locale)("posts.searchPlaceholder")` from the page.
 *
 * Missing entries for a non-English locale fall back to the English value so
 * partial coverage never produces blank UI; only English is required.
 */

type LocaleMap = { en: string } & Partial<Record<AdminLocale, string>>;

export type PageLabelKey = keyof typeof pageLabels;

