		de: "Exportieren Sie Ihre Mailchimp-Zielgruppe als CSV (Mailchimp-Dashboard → Zielgruppe → Als CSV exportieren) und laden Sie sie dann hier hoch, um Abonnenten in großen Mengen in Listmonk zu importieren. Erforderliche Spalten: ",
		pt: "Exporte sua audiência do Mailchimp como CSV (painel do Mailchimp → Audiência → Exportar como CSV), em seguida, carregue-o aqui para importar em massa assinantes para o Listmonk. Colunas obrigatórias: ",
		ja: "Mailchimp のオーディエンスを CSV としてエクスポートし（Mailchimp ダッシュボード → オーディエンス → CSV としてエクスポート）、ここにアップロードして購読者を Listmonk に一括インポートします。必須列： ",
		te: "మీ Mailchimp ప్రేక్షకులను CSV గా ఎగుమతి చేయండి (Mailchimp డాష్‌బోర్డ్ → ప్రేక్షకులు → CSV గా ఎగుమతి), ఆపై Listmonk లోకి సబ్‌స్క్రైబర్లను బల్క్-ఇంపోర్ట్ చేయడానికి ఇక్కడ అప్‌లోడ్ చేయండి. అవసరమైన నిలువు వరుసలు: ",
