		te: "వినియోగదారు సృష్టించబడ్డారు. ఇమెయిల్ డెలివరీ ప్రివ్యూ మోడ్‌లో ఉంది — ఆహ్వాన ఇమెయిల్ పంపబడలేదు. ఆహ్వానాన్ని మాన్యువల్‌గా షేర్ చేయడానికి దిగువ లింక్‌ను ఉపయోగించండి.",
		hi: "उपयोगकर्ता बनाया गया। ईमेल डिलीवरी प्रिव्यू मोड में है — कोई निमंत्रण ईमेल नहीं भेजा गया। निमंत्रण को मैन्युअल रूप से साझा करने के लिए नीचे दिए गए लिंक का उपयोग करें।",
