		te: "మార్గ-ఆధారిత నిర్మాణాత్మక పేజీలకు సాంకేతిక సవరణ. సాధారణ సంపాదకీయ ప్రవేశ స్థానం కోసం పేజీలను ఉపయోగించండి.",
		hi: "रूट-समर्थित संरचित पृष्ठों के लिए तकनीकी संपादन। सामान्य संपादकीय प्रवेश बिंदु के लिए Pages का उपयोग करें।",
