	"archives.noteBody": {
		en: "Archive metadata is edited here. Use the archive editor for public titles and SEO, and use Posts to manage the individual content that appears inside each archive.",
		ar: 'تُحرَّر بيانات الأرشيف الوصفية هنا. استخدِم محرّر الأرشيف للعناوين العامة وتحسين محركات البحث، واستخدم "المنشورات" لإدارة المحتوى الذي يظهر داخل كل أرشيف.',
		es: "Los metadatos de archivo se editan aquí. Usa el editor de archivos para títulos públicos y SEO, y usa Publicaciones para gestionar el contenido individual que aparece dentro de cada archivo.",
		fr: "Les métadonnées d'archive sont modifiées ici. Utilisez l'éditeur d'archive pour les titres publics et le SEO, et utilisez Publications pour gérer le contenu individuel qui apparaît dans chaque archive.",
		de: "Archiv-Metadaten werden hier bearbeitet. Verwenden Sie den Archiv-Editor für öffentliche Titel und SEO und Beiträge, um die einzelnen Inhalte in jedem Archiv zu verwalten.",
		pt: "Os metadados de arquivo são editados aqui. Use o editor de arquivos para títulos públicos e SEO, e use Publicações para gerenciar o conteúdo individual que aparece dentro de cada arquivo.",
		ja: "アーカイブのメタデータはここで編集します。公開タイトルとSEOにはアーカイブエディタを、各アーカイブ内に表示される個別コンテンツの管理には投稿を使用してください。",
		te: "ఆర్కైవ్ మెటాడేటా ఇక్కడ సవరించబడుతుంది. పబ్లిక్ శీర్షికలు మరియు SEO కోసం ఆర్కైవ్ ఎడిటర్‌ను ఉపయోగించండి, ప్రతి ఆర్కైవ్‌లో కనిపించే వ్యక్తిగత కంటెంట్‌ను నిర్వహించడానికి పోస్ట్‌లను ఉపయోగించండి.",
		hi: "संग्रह मेटाडेटा यहाँ संपादित किया जाता है। सार्वजनिक शीर्षकों और SEO के लिए संग्रह संपादक का उपयोग करें, और प्रत्येक संग्रह के अंदर दिखने वाली व्यक्तिगत सामग्री प्रबंधित करने के लिए Posts का उपयोग करें।",
		ny: "Metadata yosungidwa imasinthidwa pano. Gwiritsani ntchito mkonzi wa chosungidwa pa mitu yapoyera ndi SEO, ndipo gwiritsani ntchito Posts kuyang'anira zinthu zomwe zikuwoneka mkati mwa chosungidwa chilichonse.",
	},
